"use client";
import Navbar from '../../components/Nav'
import ReactPlayer from 'react-player'
import Footer from '../../components/Footer'


import { useState, useEffect } from 'react';
import axios from 'axios';

const API_BASE_URL = 'http://localhost:3000/api'; // Ajuste para sua URL

export const useAnFireAPI = () => {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const fetchAnime = async (apiKey, options = {}) => {
    const { anime_slug, anime_link, force, update } = options;
    
    setLoading(true);
    setError(null);

    try {
      const params = {
        api_key: 'mysecretapikeyxd',
        ...(anime_slug && { anime_slug }),
        ...(anime_link && { anime_link }),
        ...(force && { force }),
        ...(update && { update })
      };

      const response = await axios.get(`${API_BASE_URL}/`, { params });
      setData(response.data);
      return response.data;
    } catch (err) {
      const errorMessage = err.response?.data?.error || 'Erro ao buscar dados do anime';
      setError(errorMessage);
      throw new Error(errorMessage);
    } finally {
      setLoading(false);
    }
  };
  console.log(data);
  
  return {
    data,
    loading,
    error,
    fetchAnime
  };
};



const watchAnimes = () => {
    return (
        <>
            <Navbar />
            <h1>teste</h1>
            <ReactPlayer url='https://www.youtube.com/watch?v=_XrM4Y1wR88' />
            <Footer />
        </>
    )


}

export default watchAnimes
